use builtin::*;
verus! {
    /// Return the index of the rightmost maximum in a non‐empty array.
    ///
    /// Requires: `v.len() > 0`
    /// Ensures:
    ///   1) `i < v.len()`
    ///   2) for all `j < v.len()`, `v[j] <= v[i]`
    ///   3) for all `k` with `i < k < v.len()`, `v[k] < v[i]`
    pub fn mlast_maximum(v: &[i32]) -> (i: usize)
        requires
            v.len() > 0,
        ensures
            i < v.len(),
        ensures
            forall j: usize :: j < v.len() ==> v[j] <= v[i],
        ensures
            forall k: usize :: i < k && k < v.len() ==> v[k] < v[i],
    {
        let mut best: usize = 0;
        let mut idx: usize = 1;
        // Invariant: best is the index of the rightmost maximum among v[0..idx)
        while idx < v.len() {
            invariant idx <= v.len();
            invariant best < idx;
            invariant forall j: usize :: j < idx ==> v[j] <= v[best];
            invariant forall k: usize :: best < k && k < idx ==> v[k] < v[best];
            if v[idx] >= v[best] {
                best = idx;
            }
            idx += 1;
        }
        // At this point, idx == v.len(), and best < v.len(),
        // and best satisfies the postconditions.
        best
    }
}